int config_valid = 1;
if (gb_input.enable != 0 && gb_input.enable != 1) {
    config_valid = 0;
} else if (!isfinite(gb_config.stationary_limit) || gb_config.stationary_limit < 0.0) {
    config_valid = 0;
} else if (gb_config.required < 2 || gb_config.required > 100) {
    config_valid = 0;
}

// 2. State Transition Logic
if (config_valid == 0) {
    gb_state.mode = GB_FAULT;
} else if (gb_input.enable == 0) {
    // IDLE: Clear everything
    gb_state.mode = GB_IDLE;
    gb_state.count = 0;
    gb_state.rejected = 0;
    gb_state.sum.x = 0.0;
    gb_state.sum.y = 0.0;
    gb_state.sum.z = 0.0;
    // Bias is irrelevant in IDLE but good to keep consistent or zero
    gb_state.bias.x = 0.0;
    gb_state.bias.y = 0.0;
    gb_state.bias.z = 0.0;
} else {
    // Enable == 1

    // If already in FAULT, stay in FAULT (Latch behavior implied by lack of exit path in table)
    if (gb_state.mode == GB_FAULT) {
        // Do nothing, maintain fault state
    } else {
        // Check Sample Validity
        int sample_valid = (gb_input.sample != NULL) && adcs_is_finite_vec3(gb_input.sample);

        if (!sample_valid) {
            gb_state.mode = GB_FAULT;
        } else {
            double norm = adcs_vec3_norm(gb_input.sample);

            if (norm > gb_config.stationary_limit) {
                // Moving sample: Clear window, increment rejected
                gb_state.mode = GB_COLLECT;
                gb_state.count = 0;
                gb_state.sum.x = 0.0;
                gb_state.sum.y = 0.0;
                gb_state.sum.z = 0.0;
                gb_state.rejected++;
                // Bias remains 0 or undefined? Table implies COLLECT with bias zero for accumulation phase
                gb_state.bias.x = 0.0;
                gb_state.bias.y = 0.0;
                gb_state.bias.z = 0.0;
            } else {
                // Stationary sample
                if (gb_state.mode == GB_READY) {
                    // Freeze bias, do not update sum or count
                    // Mode remains READY
                } else {
                    // Accumulate in COLLECT
                    gb_state.mode = GB_COLLECT;
                    gb_state.sum = adcs_vec3_add(&gb_state.sum, gb_input.sample);
                    gb_state.count++;

