                        // Reached required samples
                        double scale = 1.0 / gb_state.count;
                        gb_state.bias = adcs_vec3_scale(&gb_state.sum, scale);
                        gb_state.mode = GB_READY;
                    } else {
                        // Still collecting, bias is zero per table description for intermediate steps
                        gb_state.bias.x = 0.0;
                        gb_state.bias.y = 0.0;
                        gb_state.bias.z = 0.0;
                    }
                }
            }
        }
    }
}

