gb_output.sum_energy = adcs_vec3_dot(&gb_state.sum, &gb_state.sum);

gb_output.mode = gb_state.mode;
gb_output.count = gb_state.count;
gb_output.rejected = gb_state.rejected;
gb_output.bias = gb_state.bias;

